174: static int idma_find_iova(struct iommu_domain *domain, size_t size,
175: 			  unsigned long *src_iova, unsigned long *dst_iova)
176: {
177: 	unsigned long start = domain->geometry.aperture_start;
178: 	unsigned long end = domain->geometry.aperture_end;
179: 	unsigned long iova;
180: 	size_t span = size * 2;
181: 
182: 	if (end < start || span < size || span - 1 > end - start)
183: 		return -EBUSY;
184: 
185: 	iova = ALIGN_DOWN(end - span + 1, SZ_2M);
186: 	for (;;) {
187: 		if (!idma_iova_range_free(domain, iova, span)) {
188: 			if (iova < start + SZ_2M)
189: 				break;
190: 			iova -= SZ_2M;
191: 			continue;
192: 		}
193: 
194: 		*src_iova = iova;
195: 		*dst_iova = iova + size;
196: 		return 0;
197: 	}
198: 
199: 	return -EBUSY;
200: }
