202: static int idma_iommu_map_range(struct iommu_domain *domain,
203: 				unsigned long iova, phys_addr_t phys,
204: 				size_t size, size_t pgsize)
205: {
206: 	size_t off;
207: 	int ret;
208: 
209: 	for (off = 0; off < size; off += pgsize) {
210: 		ret = iommu_map(domain, iova + off, phys + off, pgsize,
211: 				IOMMU_READ | IOMMU_WRITE, GFP_KERNEL);
212: 		if (ret) {
213: 			while (off) {
214: 				off -= pgsize;
215: 				iommu_unmap(domain, iova + off, pgsize);
216: 			}
217: 			return ret;
218: 		}
219: 	}
220: 
221: 	return 0;

265: static void idma_stream_cleanup(struct idma_stream *s)
266: {
267: 	if (!s->dev || s->retain)
268: 		return;
269: 	if (s->mapped_dst)
270: 		idma_iommu_unmap_range(s->domain, s->dst_iova, s->size, PAGE_SIZE);
271: 	if (s->mapped_src)
272: 		idma_iommu_unmap_range(s->domain, s->src_iova, s->size, PAGE_SIZE);
273: 	if (s->dst)
274: 		dma_free_attrs(s->dev, s->size, s->dst, s->dst_dma,
275: 			       DMA_ATTR_FORCE_CONTIGUOUS);
276: 	if (s->src)
277: 		dma_free_attrs(s->dev, s->size, s->src, s->src_dma,
278: 			       DMA_ATTR_FORCE_CONTIGUOUS);
279: }
