281: static int idma_stream_prepare(struct idma_stream *s, struct idma_device *idma,
282: 			       u32 pages, u32 chunk,
283: 			       struct idma_experiment_stats *stats)
284: {
285: 	struct page *src_page, *dst_page;
286: 	size_t i;
287: 	int ret;
288: 
289: 	s->idma = idma;
290: 	s->dev = idma->miscdev.parent;
291: 	s->stats = stats;
292: 	s->domain = iommu_get_domain_for_dev(s->dev);
293: 	if (!s->domain || s->domain->type == IOMMU_DOMAIN_IDENTITY)
294: 		return -EOPNOTSUPP;
295: 	s->size = (size_t)pages * PAGE_SIZE;
296: 	s->chunk = chunk;
297: 	s->src = dma_alloc_attrs(s->dev, s->size, &s->src_dma, GFP_KERNEL,
298: 				 DMA_ATTR_FORCE_CONTIGUOUS);
299: 	if (!s->src)
300: 		return -ENOMEM;
301: 	s->dst = dma_alloc_attrs(s->dev, s->size, &s->dst_dma, GFP_KERNEL,
302: 				 DMA_ATTR_FORCE_CONTIGUOUS);
303: 	if (!s->dst)
304: 		return -ENOMEM;
305: 	for (i = 0; i < s->size / sizeof(u64); i++) {
306: 		((u64 *)s->src)[i] = idma_pattern(s, i);
307: 		((u64 *)s->dst)[i] = ~idma_pattern(s, i);
308: 	}
309: 	src_page = idma_buffer_page(s->src);
310: 	dst_page = idma_buffer_page(s->dst);
311: 	if (!src_page || !dst_page)
312: 		return -EFAULT;
313: 	ret = idma_find_iova(s->domain, s->size, &s->src_iova, &s->dst_iova);
314: 	if (ret)
315: 		return ret;
316: 	ret = idma_iommu_map_range(s->domain, s->src_iova,
317: 				  page_to_phys(src_page), s->size, PAGE_SIZE);
318: 	if (ret)
319: 		return ret;
320: 	s->mapped_src = true;
321: 	ret = idma_iommu_map_range(s->domain, s->dst_iova,
322: 				  page_to_phys(dst_page), s->size, PAGE_SIZE);
323: 	if (ret)
324: 		return ret;
325: 	s->mapped_dst = true;

29: static inline size_t get_page_size(size_t size)
30: {
31: 	if (size >= IOMMU_PAGE_SIZE_512G)
32: 		return IOMMU_PAGE_SIZE_512G;
33: 
34: 	if (size >= IOMMU_PAGE_SIZE_1G)
35: 		return IOMMU_PAGE_SIZE_1G;
36: 
37: 	if (size >= IOMMU_PAGE_SIZE_2M)
38: 		return IOMMU_PAGE_SIZE_2M;
39: 
40: 	return IOMMU_PAGE_SIZE_4K;

75: static pte_t *riscv_iommu_pt_walk_alloc(pmd_t * ptp, unsigned long iova,
76: 					unsigned shift, bool root,
77: 					size_t pgsize,
78: 					unsigned long (*pd_alloc)(gfp_t),
79: 					gfp_t gfp)
80: {
81: 	pmd_t *pte;
82: 	unsigned long pfn;
83: 
84: 	if (root)
85: 		pte = ptp + ((iova >> shift) & (PTRS_PER_PMD - 1));
86: 	else
87: 		pte = (pmd_t *) pfn_to_virt(__page_val_to_pfn(pmd_val(*ptp))) +
88: 		    ((iova >> shift) & (PTRS_PER_PMD - 1));
89: 
90: 	if ((1ULL << shift) <= pgsize) {
91: 		if (pmd_present(*pte) && !pmd_leaf(*pte))
92: 			riscv_iommu_pt_walk_free(pte, shift - 9, false);
93: 		return (pte_t *) pte;
94: 	}
95: 
96: 	if (pmd_none(*pte)) {
97: 		pfn = pd_alloc ? virt_to_pfn(pd_alloc(gfp)) : 0;
98: 		if (!pfn)
99: 			return NULL;
100: 		set_pmd(pte, __pmd((pfn << _PAGE_PFN_SHIFT) | _PAGE_TABLE));
101: 	}
102: 
103: 	return riscv_iommu_pt_walk_alloc(pte, iova, shift - 9, false,
104: 					 pgsize, pd_alloc, gfp);
105: }
